CREATE PROCEDURE GetEmployeesByDept @DeptId INT AS
BEGIN
  SET NOCOUNT ON;
  SELECT EmpId, Name, Salary FROM Employees WHERE DeptId = @DeptId;
  UPDATE AuditLog SET LastRun = GETDATE(); -- DML allowed
END;

CREATE FUNCTION dbo.GetAnnualSalary (@Monthly DECIMAL(10,2))
RETURNS DECIMAL(12,2) AS
BEGIN
  RETURN @Monthly * 12;
END;

SELECT Name, dbo.GetAnnualSalary(Salary) FROM Employees; -- usable in SELECT

CREATE VIEW vw_ActiveEmployees AS
SELECT e.EmpId, e.Name, d.DeptName FROM Employees e
JOIN Departments d ON e.DeptId = d.DeptId WHERE e.IsActive = 1;

SELECT * FROM vw_ActiveEmployees WHERE DeptName = 'IT'; -- query like a table

CREATE CLUSTERED INDEX IX_Orders_OrderId ON Orders(OrderId);

CREATE NONCLUSTERED INDEX IX_Orders_Cust_Date
ON Orders (CustomerId, OrderDate) INCLUDE (Amount);

-- This query is now fully 'covered' -- no Key Lookup needed
SELECT CustomerId, OrderDate, Amount
FROM Orders
WHERE CustomerId = 42 AND OrderDate >= '2026-01-01';

-- In SSMS: Ctrl+M, then run the query to see the Actual Execution Plan
SELECT o.OrderId, c.Name, o.Amount
FROM Orders o
JOIN Customers c ON o.CustomerId = c.CustomerId
WHERE o.OrderDate >= '2026-01-01';

