UPDATE STATISTICS Customers;

CREATE PROCEDURE TransferMoney @FromId INT, @ToId INT, @Amount DECIMAL(10,2)
AS
BEGIN
  SET NOCOUNT ON;
  SET XACT_ABORT ON; -- auto-rollback on severe errors
  BEGIN TRY
    BEGIN TRANSACTION;
    IF (SELECT Balance FROM Accounts WHERE Id = @FromId) < @Amount
      THROW 50001, 'Insufficient balance', 1;

    UPDATE Accounts SET Balance = Balance - @Amount WHERE Id = @FromId;
    UPDATE Accounts SET Balance = Balance + @Amount WHERE Id = @ToId;
    INSERT INTO TransferLog (FromId, ToId, Amount) VALUES (@FromId, @ToId, @Amount);

    COMMIT TRANSACTION;
  END TRY
  BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    INSERT INTO ErrorLog (Message, ProcName) VALUES (ERROR_MESSAGE(), ERROR_PROCEDURE());
    THROW; -- rethrow so the caller knows
  END CATCH
END

