-- TCL: TRUNCATE IS transactional in SQL Server
BEGIN TRANSACTION;
TRUNCATE TABLE Orders; -- 0 rows now
ROLLBACK; -- rows are BACK

WITH HighPaid AS (
  SELECT EmpId, Name, Salary FROM Employees WHERE Salary > 50000
)
SELECT * FROM HighPaid ORDER BY Salary DESC;

-- Recursive -- only a CTE can do this
WITH EmpHierarchy AS (
  SELECT EmpId, Name, ManagerId, 1 AS Level FROM Employees WHERE ManagerId IS NULL
  UNION ALL
  SELECT e.EmpId, e.Name, e.ManagerId, h.Level + 1
  FROM Employees e JOIN EmpHierarchy h ON e.ManagerId = h.EmpId
)
SELECT * FROM EmpHierarchy;

CREATE TABLE #TempSales (ProductId INT, Total DECIMAL(10,2));
CREATE INDEX IX_Temp ON #TempSales(ProductId); -- can index

-- De-duplicate
WITH N AS (
  SELECT *, ROW_NUMBER() OVER (PARTITION BY Email ORDER BY EmpId) rn FROM Employees
)
DELETE FROM N WHERE rn > 1;

-- 5th highest SALARY (handles ties correctly)
WITH R AS (
  SELECT Name, Salary, DENSE_RANK() OVER (ORDER BY Salary DESC) rnk FROM Employees
)
SELECT Name, Salary FROM R WHERE rnk = 5;

-- Alternatives
SELECT DISTINCT Salary FROM Employees ORDER BY Salary DESC OFFSET 4 ROWS FETCH NEXT 1 ROWS ONLY;
SELECT TOP 3 WITH TIES Name, Salary FROM Employees ORDER BY Salary DESC;

SELECT c.CustomerId FROM Customers c
WHERE NOT EXISTS (SELECT 1 FROM Orders o WHERE o.CustomerId = c.CustomerId);

-- THE TRAP:
SELECT * FROM Customers WHERE CustomerId NOT IN (SELECT CustomerId FROM Orders);
-- ONE NULL in Orders.CustomerId -> ZERO rows returned. Prefer NOT EXISTS.

CREATE PARTITION FUNCTION pf_OrderYear (DATE)
AS RANGE RIGHT FOR VALUES ('2024-01-01', '2025-01-01', '2026-01-01');

CREATE PARTITION SCHEME ps_OrderYear AS PARTITION pf_OrderYear ALL TO ([PRIMARY]);

CREATE TABLE Orders (
  OrderId INT IDENTITY, OrderDate DATE NOT NULL, Amount DECIMAL(10,2),
  CONSTRAINT PK_Orders PRIMARY KEY (OrderDate, OrderId)
) ON ps_OrderYear (OrderDate);

SELECT OrderId, $PARTITION.pf_OrderYear(OrderDate) AS PartitionNo FROM Orders;

DECLARE emp_cursor CURSOR LOCAL FAST_FORWARD FOR SELECT EmpId, Name FROM Employees;
OPEN emp_cursor;
FETCH NEXT FROM emp_cursor INTO @EmpId, @Name;
WHILE @@FETCH_STATUS = 0 -- 0 = success, -1 = no more rows
BEGIN
  EXEC SendAppraisalEmail @EmpId; -- a per-row action a SET can't do
  FETCH NEXT FROM emp_cursor INTO @EmpId, @Name;
END
CLOSE emp_cursor; DEALLOCATE emp_cursor;

-- Set-based replacement (0.2s vs ~30s)
UPDATE Employees SET Salary = Salary * 1.10 WHERE DeptId = 2;

-- WHILE loop for safe BATCHING of large DML
WHILE 1 = 1
BEGIN
  DELETE TOP (5000) FROM Orders WHERE OrderDate < '2020-01-01';
  IF @@ROWCOUNT = 0 BREAK;
  WAITFOR DELAY '00:00:01'; -- release locks between batches
END
